        unsigned IDMAC_EOBND_EN_21 : 1; //!< [21] end-of-band indication of Channel interrupt.
        unsigned IDMAC_EOBND_EN_22 : 1; //!< [22] end-of-band indication of Channel interrupt.
        unsigned RESERVED3 : 2; //!< [24:23] Reserved.
