#define HW_IPU_MEM_RST_SET(x, v)    (HW_IPU_MEM_RST_WR(x, HW_IPU_MEM_RST_RD(x) |  (v)))
#define HW_IPU_MEM_RST_CLR(x, v)    (HW_IPU_MEM_RST_WR(x, HW_IPU_MEM_RST_RD(x) & ~(v)))
