{
    reg32_t U;
    struct _hw_ipu_int_stat_4_bitfields
    {
        unsigned RESERVED0 : 1; //!< [0] Reserved.
        unsigned IDMAC_NFACK_33 : 1; //!< [1] Enable New Frame Ack of Channel interrupt.
        unsigned RESERVED1 : 6; //!< [7:2] Reserved.
        unsigned IDMAC_NFACK_40 : 1; //!< [8] Enable New Frame Ack of Channel interrupt.
        unsigned IDMAC_NFACK_41 : 1; //!< [9] Enable New Frame Ack of Channel interrupt.
        unsigned IDMAC_NFACK_42 : 1; //!< [10] Enable New Frame Ack of Channel interrupt.
        unsigned IDMAC_NFACK_43 : 1; //!< [11] Enable New Frame Ack of Channel interrupt.
        unsigned IDMAC_NFACK_44 : 1; //!< [12] Enable New Frame Ack of Channel interrupt.
        unsigned IDMAC_NFACK_45 : 1; //!< [13] Enable New Frame Ack of Channel interrupt.
        unsigned IDMAC_NFACK_46 : 1; //!< [14] Enable New Frame Ack of Channel interrupt.
        unsigned IDMAC_NFACK_47 : 1; //!< [15] Enable New Frame Ack of Channel interrupt.
        unsigned IDMAC_NFACK_48 : 1; //!< [16] Enable New Frame Ack of Channel interrupt.
        unsigned IDMAC_NFACK_49 : 1; //!< [17] Enable New Frame Ack of Channel interrupt.
        unsigned IDMAC_NFACK_50 : 1; //!< [18] Enable New Frame Ack of Channel interrupt.
        unsigned IDMAC_NFACK_51 : 1; //!< [19] Enable New Frame Ack of Channel interrupt.
        unsigned IDMAC_NFACK_52 : 1; //!< [20] Enable New Frame Ack of Channel interrupt.
        unsigned RESERVED2 : 11; //!< [31:21] Reserved.
    } B;
} hw_ipu_int_stat_4_t;
#endif

