#ifndef __LANGUAGE_ASM__
/*!
 * @brief HW_IPU_INT_STAT_9 - Interrupt Status Register 9 (W1C)
 *
 * Reset value: 0x00000000
 *
 * IPU status registers are not stored in the SRM during power gating mode.This register contains
 * part of IPU interrupts status bits. This register holds the error interrupt indications coming
 * from different modules within All the bits in this register are write one to clear.
 */
typedef union _hw_ipu_int_stat_9
{
    reg32_t U;
    struct _hw_ipu_int_stat_9_bitfields
    {
        unsigned VDI_FIFO1_OVF : 1; //!< [0] FIFO1 overflow Interrupt1
        unsigned RESERVED0 : 25; //!< [25:1] Reserved
        unsigned IC_BAYER_BUF_OVF : 1; //!< [26] This bit indicates on an interrupt that is a result of the IC Buffer overflow for Bayer coming from the IC.
        unsigned IC_ENC_BUF_OVF : 1; //!< [27] This bit indicates on an interrupt that is a result of the IC Buffer overflow for encoding coming from the IC.
        unsigned IC_VF_BUF_OVF : 1; //!< [28] This bit indicates on an interrupt that is a result of the IC Buffer overflow for view finder coming from the IC.
        unsigned RESERVED1 : 1; //!< [29] Reserved
        unsigned CSI0_PUPE : 1; //!< [30] CSI0_PUPE - CSI0 parameters update error interrupt.
        unsigned CSI1_PUPE : 1; //!< [31] CSI1_PUPE - CSI1 parameters update error interrupt.
    } B;
} hw_ipu_int_stat_9_t;
#endif

