#ifndef __LANGUAGE_ASM__
/*!
 * @brief HW_IPU_INT_STAT_10 - Interrupt Status Register 10 (W1C)
 *
 * Reset value: 0x00000000
 *
 * IPU status registers are not stored in the SRM during power gating mode.This register contains
 * part of IPU interrupts status bits. This register holds error interrupt indications coming from
 * different modules within All the bits in this register are write one to clear.
 */
typedef union _hw_ipu_int_stat_10
{
    reg32_t U;
    struct _hw_ipu_int_stat_10_bitfields
    {
        unsigned SMFC0_FRM_LOST : 1; //!< [0] Frame Lost of SMFC channel 0 interrupt.
        unsigned SMFC1_FRM_LOST : 1; //!< [1] Frame Lost of SMFC channel 1 interrupt.
        unsigned SMFC2_FRM_LOST : 1; //!< [2] Frame Lost of SMFC channel 2 interrupt.
        unsigned SMFC3_FRM_LOST : 1; //!< [3] Frame Lost of SMFC channel 3 interrupt.
        unsigned RESERVED0 : 12; //!< [15:4] Reserved
        unsigned DC_TEARING_ERR_1 : 1; //!< [16] Tearing Error #1 interrupt
        unsigned DC_TEARING_ERR_2 : 1; //!< [17] Tearing Error #2 interrupt
        unsigned DC_TEARING_ERR_6 : 1; //!< [18] Tearing Error #6 interrupt
        unsigned DI0_SYNC_DISP_ERR : 1; //!< [19] DI0 Synchronous display error interrupt
        unsigned DI1_SYNC_DISP_ERR : 1; //!< [20] DI1 Synchronous display error interrupt
        unsigned DI0_TIME_OUT_ERR : 1; //!< [21] DI0 time out error interrupt
        unsigned DI1_TIME_OUT_ERR : 1; //!< [22] DI1 time out error interrupt
        unsigned RESERVED1 : 1; //!< [23] Reserved
        unsigned IC_VF_FRM_LOST_ERR : 1; //!< [24] This bit indicates on an interrupt that is a result of IC's view finder frame lost.
        unsigned IC_ENC_FRM_LOST_ERR : 1; //!< [25] This bit indicates on an interrupt that is a result of IC's encoding frame lost.
        unsigned IC_BAYER_FRM_LOST_ERR : 1; //!< [26] This bit indicates on an interrupt that is a result of IC's Bayer frame lost.
        unsigned RESERVED2 : 1; //!< [27] Reserved
        unsigned NON_PRIVILEGED_ACC_ERR : 1; //!< [28] Non Privileged Access Error interrupt.
        unsigned AXIW_ERR : 1; //!< [29] This bit indicates on an interrupt that is a result of AXI write access resulted with error response.
        unsigned AXIR_ERR : 1; //!< [30] This bit indicates on an interrupt that is a result of AXI read access resulted with error response.
        unsigned RESERVED3 : 1; //!< [31] Reserved
    } B;
} hw_ipu_int_stat_10_t;
#endif

