//-------------------------------------------------------------------------------------------
// HW_IPU_SRM_STAT - Shadow Registers Memory Status Register
//-------------------------------------------------------------------------------------------

#ifndef __LANGUAGE_ASM__
/*!
 * @brief HW_IPU_SRM_STAT - Shadow Registers Memory Status Register (RO)
 *
 * Reset value: 0x00000000
 *
 * The register contains status bits of SRM updates. There is a bit for each block. The bit is set
 * when the SRM is currently updating the module's registers. When the SRM completes updating the
 * registers of the block the bit is cleared. SW should not update the block's registers while it is
 * being updated by the SRM.
 */
typedef union _hw_ipu_srm_stat
{
    reg32_t U;
    struct _hw_ipu_srm_stat_bitfields
    {
        unsigned DP_S_SRM_STAT : 1; //!< [0] DP SYNC FLOW SRM STAT
        unsigned DP_A0_SRM_STAT : 1; //!< [1] DP ASYNC0 FLOW SRM STAT
        unsigned DP_A1_SRM_STAT : 1; //!< [2] DP ASYNC1 FLOW SRM STAT
        unsigned RESERVED0 : 1; //!< [3] Reserved
        unsigned DC_2_SRM_STAT : 1; //!< [4] DC group #2 SRM STAT
        unsigned DC_6_SRM_STAT : 1; //!< [5] DC group #6 SRM STAT
        unsigned CSI0_SRM_STAT : 1; //!< [6] CSI1_SRM_STAT
        unsigned CSI1_SRM_STAT : 1; //!< [7] CSI1_SRM_STAT
        unsigned DI0_SRM_STAT : 1; //!< [8] DI0 SRM STAT
        unsigned DI1_SRM_STAT : 1; //!< [9] DI1 SRM STAT
        unsigned RESERVED1 : 22; //!< [31:10] Reserved
    } B;
} hw_ipu_srm_stat_t;
#endif

