//! @brief Format value for bitfield IPU_CSI0_SKIP_CSI0_SKIP_SMFC.
#define BF_IPU_CSI0_SKIP_CSI0_SKIP_SMFC(v)   ((__REG_VALUE_TYPE((v), reg32_t) << BP_IPU_CSI0_SKIP_CSI0_SKIP_SMFC) & BM_IPU_CSI0_SKIP_CSI0_SKIP_SMFC)

#ifndef __LANGUAGE_ASM__
//! @brief Set the CSI0_SKIP_SMFC field to a new value.
#define BW_IPU_CSI0_SKIP_CSI0_SKIP_SMFC(x, v)   (HW_IPU_CSI0_SKIP_WR(x, (HW_IPU_CSI0_SKIP_RD(x) & ~BM_IPU_CSI0_SKIP_CSI0_SKIP_SMFC) | BF_IPU_CSI0_SKIP_CSI0_SKIP_SMFC(v)))
#endif
//@}

/*! @name Register IPU_CSI0_SKIP, field CSI0_ID_2_SKIP[9:8] (RW)
 *
 * CSI0 to SMFC Skipping ID. Data from the CSI0 to the SMFC has an ID associated with it. The ID is
 * received from the MIPI interface. The skipping mechanism between the CSI0 and the SMFC can be
 * used for only one ID. There is no skipping for data coming with ID different from the ID
 * programed in this bits
 *
 * Values:
 * - 00 - - Skipping mechanism is activated on frames with ID equal to 00
 * - 01 - - Skipping mechanism is activated on frames with ID equal to 01
 * - 10 - - Skipping mechanism is activated on frames with ID equal to 10
 * - 11 - - Skipping mechanism is activated on frames with ID equal to 11
 */
//@{
#define BP_IPU_CSI0_SKIP_CSI0_ID_2_SKIP      (8)      //!< Bit position for IPU_CSI0_SKIP_CSI0_ID_2_SKIP.
