#define BW_IPU_CSI0_SKIP_CSI0_ID_2_SKIP(x, v)   (HW_IPU_CSI0_SKIP_WR(x, (HW_IPU_CSI0_SKIP_RD(x) & ~BM_IPU_CSI0_SKIP_CSI0_ID_2_SKIP) | BF_IPU_CSI0_SKIP_CSI0_ID_2_SKIP(v)))
