/*!
 * @brief HW_IPU_SMFC_WMC - SMFC Watermark Control Register (RW)
 *
 * Reset value: 0x000009a6
 *
 * The purpose of this register is to control watermarks levels of DMA channels. The bit setting
 * given relative to FIFO size and not in number of words since FIFO size depend from number of
 * enabled DMA channels.
 */
typedef union _hw_ipu_smfc_wmc
{
    reg32_t U;
    struct _hw_ipu_smfc_wmc_bitfields
    {
        unsigned WM0_SET : 3; //!< [2:0] Watermark "set" level of DMASMFC channel 0.
        unsigned WM0_CLR : 3; //!< [5:3] Watermark "clear" level of DMASMFC channel 0.
        unsigned WM1_SET : 3; //!< [8:6] Watermark "set" level of DMASMFC channel 1.
        unsigned WM1_CLR : 3; //!< [11:9] Watermark "clear" level of DMASMFC channel 1.
        unsigned RESERVED0 : 4; //!< [15:12] Reserved.
        unsigned WM2_SET : 3; //!< [18:16] Watermark "set" level of DMASMFC channel 2.
        unsigned WM2_CLR : 3; //!< [21:19] Watermark "clear" level of DMASMFC channel 2.
        unsigned WM3_SET : 3; //!< [24:22] Watermark "set" level of DMASMFC channel 3
        unsigned WM3_CLR : 3; //!< [27:25] Watermark "clear" level of DMASMFC channel 3.
        unsigned RESERVED1 : 4; //!< [31:28] Reserved.
    } B;
} hw_ipu_smfc_wmc_t;
#endif

